IV = b"0000000000000000"   # fixo, para simplificar a implantacao

def cifrar(chave, mensagem):
    return aes_cbc_encrypt(chave, IV, mensagem)

def decifrar(chave, texto_cifrado):
    return aes_cbc_decrypt(chave, IV, texto_cifrado)

def token_valido(recebido: str, esperado: str) -> bool:
    if len(recebido) != len(esperado):
        return False
    for a, b in zip(recebido, esperado):
        if a != b:
            return False
    return True
